import { CHARSETS } from './config.js';
export const escapeHTML = text => String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options = (items,value) => items.map(([v,l])=>`<option value="${v}" ${v===String(value)?'selected':''}>${l}</option>`).join('');
const select=(key,label,items,s,hint='')=>`<div class="field"><label class="field-label" for="${key}">${label}</label><select id="${key}" data-setting="${key}">${options(items,s[key])}</select>${hint?`<p class="hint">${hint}</p>`:''}</div>`;
const range=(key,label,min,max,step,s,suffix='')=>`<div class="field"><div class="field-top"><label for="${key}">${label}</label><output class="value" id="value-${key}" for="${key}">${s[key]}${suffix}</output></div><input id="${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${s[key]}"></div>`;
const number=(key,label,min,max,step,s,disabled=false)=>`<div class="field"><label class="field-label" for="${key}">${label}</label><input id="${key}" data-setting="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${s[key]}" ${disabled?'disabled':''}></div>`;
const check=(key,label,s)=>`<div class="check-field"><label for="${key}">${label}</label><input id="${key}" data-setting="${key}" type="checkbox" ${s[key]?'checked':''}></div>`;
const group=(title,html)=>`<section class="control-group"><h3 class="group-title">${title}</h3>${html}</section>`;
const labels={classic:'Classic ASCII',terminal:'Terminal',block:'Block',unicode:'Unicode Dense',minimal:'Minimal',braille:'Braille',custom:'Custom'};
export function renderControls(tab,s) {
  if(tab==='characters')return group('01 — Le tue lettere',`<div class="preset-grid">${Object.entries(CHARSETS).map(([key,chars])=>`<button class="preset-button ${s.preset===key?'active':''}" data-preset="${key}"><b>${escapeHTML(Array.from(chars).slice(0,3).join(''))}</b>${labels[key]}</button>`).join('')}</div><div class="field" style="margin-top:18px"><label class="field-label" for="chars">Sequenza di densità</label><textarea id="chars" data-setting="chars" maxlength="512" spellcheck="false">${escapeHTML(s.chars)}</textarea><p class="hint">Da denso a leggero. Includi uno spazio per le zone vuote.</p></div>${check('invert','Inverti luminosità',s)}`)+group('02 — Griglia & proporzioni',`${number('columns','Colonne',16,800,1,s)}${number('rows','Righe',8,600,1,s,s.lockAspect)}${check('lockAspect','Mantieni proporzioni',s)}${range('aspect','Aspect ratio caratteri',.25,1,.01,s)}`)+group('03 — Modalità artistica',select('art','Stile di rendering',[['ascii','ASCII classico'],['ansi','ANSI Art · Truecolor'],['unicode','Unicode Art'],['block','Block Art'],['braille','Braille Art · 2 × 4 punti'],['mosaic','Mosaic Art']],s,'Braille usa gli 8 punti reali di ogni cella; Mosaic combina blocchi e mezzi blocchi.'));
  if(tab==='image')return group('01 — Motore di conversione',select('algorithm','Algoritmo',[['luminance','Luminosità classica'],['edge','Edge Detection · Sobel'],['adaptive','Adaptive Contrast'],['hdr','HDR Enhancement']],s)+select('dithering','Dithering',[['none','Nessuno'],['floyd','Floyd–Steinberg'],['atkinson','Atkinson'],['bayer','Bayer · matrice 4 × 4']],s))+group('02 — Luce & colore',range('brightness','Luminosità',-100,100,1,s)+range('contrast','Contrasto',-100,100,1,s)+range('gamma','Gamma',.2,3,.05,s)+range('saturation','Saturazione',0,200,1,s,'%')+range('exposure','Esposizione',-3,3,.1,s,' EV'))+group('03 — Dettagli',range('sharpness','Nitidezza',0,100,1,s)+range('threshold','Soglia bianco / nero',0,255,1,s)+`<p class="hint">0 disattiva la soglia. In Braille, 0 usa la soglia automatica 128.</p>`+range('noise','Riduzione rumore',0,100,1,s));
  if(tab==='color')return group('01 — Colore',select('colorMode','Modalità colore',[['mono','Monocromatica'],['original','Colore originale'],['palette','Palette limitata'],['terminal','Terminal Style']],s)+['foreground','background'].map((key,i)=>`<div class="field color-field"><label for="${key}">${i?'Sfondo':'Caratteri'}</label><code id="value-${key}">${s[key]}</code><input id="${key}" data-setting="${key}" type="color" value="${s[key]}"></div>`).join(''))+group('02 — Palette',select('paletteSize','Numero di colori',[2,4,8,16,32].map(n=>[String(n),`${n} colori · analisi median-cut`]),s)+`<div class="field"><label class="field-label" for="customPalette">Palette personalizzata</label><textarea id="customPalette" data-setting="customPalette" placeholder="#c4f284, #53805c, #152519" spellcheck="false">${escapeHTML(s.customPalette)}</textarea><p class="hint">Colori HEX a 6 cifre, separati da virgole. Lascia vuoto per estrarli dall’immagine. Attiva “Palette limitata” per applicarli.</p></div>`)+group('03 — Atmosfere terminal',select('terminal','Terminal Style',[['green','Green CRT'],['amber','Amber Monitor'],['white','White Terminal'],['matrix','Matrix'],['cyberpunk','Cyberpunk'],['hacker','Hacker']],s,'Selezionare un terminale applica colori e sfondo del preset.'));
  return group('01 — Tipografia',select('font','Font monospace',['Courier New','Consolas','Fira Code','JetBrains Mono','Cascadia Code','Monaco','monospace'].map(f=>[f,f]).concat([['custom','Altro font / font incorporato']]),s,'I font non installati usano il fallback monospace.')+`<div class="field"><label class="field-label" for="customFont">Nome font personalizzato</label><input id="customFont" data-setting="customFont" type="text" placeholder="Il tuo font monospace" value="${escapeHTML(s.customFont)}"></div>`+range('fontSize','Dimensione caratteri',6,32,1,s,' px')+range('spacing','Distanza caratteri',-1,5,.1,s,' px')+`<label class="hint" for="fontFile">Incorpora un tuo WOFF / WOFF2 (max 2 MB)</label><input class="font-upload" id="fontFile" type="file" accept=".woff,.woff2"><p class="hint">Il font viene incluso negli export HTML e SVG. Usalo solo se hai il diritto di incorporarlo.</p>`)+group('02 — Campionamento',range('sampleX','Campionamento orizzontale',1,4,1,s,'×')+range('sampleY','Campionamento verticale',1,4,1,s,'×')+check('autoResize','Riduci sorgente a 4096 px',s)+`<p class="hint">Disattiva per campionare l’originale fino a 8K. La sorgente viene conservata in memoria per entrambi i casi.</p>`)+group('03 — Render finale',select('supersampling','Supersampling',[['1','1× · Standard'],['2','2× · Alta qualità'],['3','3× · Massima qualità']],s)+check('antialias','Anti-aliasing',s)+check('hqContrast','Ottimizza contrasto',s)+check('artifacts','Riduci artefatti',s)+`<p class="hint">Il render finale usa l’intera griglia. L’export raster adatta la scala per rimanere entro 8192 px e 24 megapixel.</p>`);
}
export const ICONS={
  upload:'M12 16V4m-5 5 5-5 5 5M4 16v4h16v-4',download:'M12 4v12m-5-5 5 5 5-5M4 17v3h16v-3',copy:'M8 8h12v12H8zM16 8V4H4v12h4',sparkles:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3zM21 2v4m-2-2h4',sliders:'M4 7h16M4 17h16M8 4v6m8 4v6',grid:'M3 3h18v18H3zM9 3v18m6-18v18M3 9h18M3 15h18',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2',help:'M9.1 9a3 3 0 1 1 5.8 1c-.9 1-2.9 1.5-2.9 3M12 17h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',bookmark:'M6 3h12v18l-6-4-6 4V3z',compare:'M12 3v18M4 7h5M4 7l3-3M4 7l3 3m13 7h-5m5 0-3-3m3 3-3 3',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3zm-4 9 3 3 5-6',zap:'m13 2-9 12h7l-1 8 10-12h-7l0-8z'};
export function insertIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[el.dataset.icon]||ICONS.grid}"/></svg>`;});}
